test('handoff budget 초기검사 거절도 이동한 원 frame·secret을 폐기하고 수용/SIGN/native 추가0이다',async()=>{
 const {NativeFirstReceiveFrameDecoder:Decoder}=await import('../../../apps/connector/runtime/native-first-receive-client.ts'),push=Decoder.prototype.push,finish=Decoder.prototype.finish,frames:Uint8Array[]=[],secrets:Uint8Array[]=[];Decoder.prototype.push=function(raw:Uint8Array){frames.push(raw);return Reflect.apply(push,this,[raw]);};Decoder.prototype.finish=function(){const value=Reflect.apply(finish,this,[]);if((value.metadata as any).snapshot?.purpose==='NATIVE_FIRST_RECEIVE_DELIVERY')secrets.push(value.secret);return value;};let f:any;try{f=await phaseHttpFixture('STREAM');await f.client.consumeReceivePhase(f.input.window,f.input.challenge,f.input.request,f.input.body,f.source);assert.ok(frames.some(bytes=>bytes.some(byte=>byte!==0)));assert.equal(secrets.length,1);const count=f.state.native,signs=f.state.signs;f.state.now=Date.parse(f.delivery.snapshot.expiresAt);await assert.rejects(f.client.handoffReceiveDelivery(null),/CONTEXT_CHANGED/);assert.ok(frames.every(bytes=>bytes.every(byte=>byte===0)));assert.ok(secrets.every(bytes=>bytes.every(byte=>byte===0)));await assert.rejects(f.client.handoffReceiveDelivery(null));assert.equal(f.state.native,count);assert.equal(f.state.signs,signs);}finally{f?.client.disposeReceive();for(const bytes of [...frames,...secrets])bytes.fill(0);Decoder.prototype.push=push;Decoder.prototype.finish=finish;if(f)assert.equal(f.timers.size,0);}
});


