test('실제 private STREAM Delivery의 currentSource는 기존 Native current를 읽고 slot 재귀 없이 소유43B를 폐기한다',async()=>{
 const f=await phaseHttpFixture('STREAM');let loan:any;try{await f.client.consumeReceivePhase(f.input.window,f.input.challenge,f.input.request,f.input.body,f.source);assert.equal(typeof f.client.createDeliveryCurrentSource,'function','private Delivery 기반 concrete currentSource producer 부재');loan=f.client.createDeliveryCurrentSource();assert.deepEqual(Object.keys(loan).sort(),['close','source']);assert.deepEqual(Object.keys(loan.source).sort(),['binding','read','transport']);const value=await loan.source.read(new AbortController().signal);assert.deepEqual(value.authority,f.delivery.snapshot.authority);assert.equal(value.current.phase,'RESERVED');assert.equal(value.current.codingAgentExecutionAuthorized,false);assert.equal(value.current.agentDispatchPerformed,false);assert.equal(f.state.currentReads,1);assert.equal(JSON.stringify(value).includes('X'.repeat(43)),false);loan.close();await assert.rejects(loan.source.read(new AbortController().signal));assert.equal(f.state.currentReads,1);}finally{loan?.close();f.client.disposeReceive();assert.equal(f.timers.size,0);}
});


test('private currentSource는 수용전·회수 profile·교차 Native ref·원기한·abort와 dispose에서 새 IO0·소유43B wipe를 유지한다',async()=>{
 for(const mode of ['BEFORE','PROFILE_REVOKED','CURRENT_REF','MINIMUM','ABORT','DISPOSE']){const f=await phaseHttpFixture('STREAM'),owned:Buffer[]=[];let loan:any;try{if(mode==='BEFORE'){assert.throws(()=>f.client.createDeliveryCurrentSource());assert.equal(f.state.currentReads,undefined);continue;}await f.client.consumeReceivePhase(f.input.window,f.input.challenge,f.input.request,f.input.body,f.source);const from=Buffer.from;try{(Buffer as any).from=(...args:any[])=>{const value=Reflect.apply(from,Buffer,args)as Buffer;if(args[0] instanceof Uint8Array&&args[0].byteLength===43)owned.push(value);return value;};loan=f.client.createDeliveryCurrentSource();}finally{Buffer.from=from;}assert.equal(owned.length,1);assert.equal(owned[0]!.toString('ascii'),'X'.repeat(43));assert.throws(()=>f.client.createDeliveryCurrentSource());
 if(mode==='DISPOSE'){f.client.disposeReceive();await assert.rejects(loan.source.read(new AbortController().signal));assert.equal(f.state.currentReads,undefined);}else if(mode==='MINIMUM'){f.state.currentExpires=new Date(f.state.now+2000).toISOString();const value=await loan.source.read(new AbortController().signal);assert.equal(value.profileExpiresAt,f.state.currentExpires);assert.equal(value.signerExpiresAt,f.state.currentExpires);f.state.now+=2000;await assert.rejects(loan.source.read(new AbortController().signal));assert.equal(f.state.currentReads,1);}else if(mode==='ABORT'){f.state.currentMode='HOLD';const controller=new AbortController(),pending=loan.source.read(controller.signal);for(let i=0;i<300&&!f.state.releaseCurrent;i++)await Promise.resolve();assert.equal(typeof f.state.releaseCurrent,'function');controller.abort();await assert.rejects(pending);f.state.releaseCurrent();await assert.rejects(loan.source.read(new AbortController().signal));assert.equal(f.state.currentReads,1);}else{f.state.currentMode=mode;await assert.rejects(loan.source.read(new AbortController().signal));assert.equal(f.state.currentReads,mode==='PROFILE_REVOKED'?undefined:1);}
 assert.ok(owned.every(buffer=>buffer.every(byte=>byte===0)),'생산자가 소유한 mutable43B는 실패/회수/종료에 폐기한다');}finally{loan?.close();f.client.disposeReceive();assert.equal(f.timers.size,0);}}
});


test('currentSource 보호 ProfileRead는 원 Window와 같은 유효한 8192 초과 CA 응답을 기존 2MiB cap으로 소비한다',async()=>{
 const f=await phaseHttpFixture('STREAM',false,false,10000,10000);let loan:any;try{await f.client.consumeReceivePhase(f.input.window,f.input.challenge,f.input.request,f.input.body,f.source);loan=f.client.createDeliveryCurrentSource();const value=await loan.source.read(new AbortController().signal);assert.equal(Buffer.byteLength(value.ca),10000);assert.equal(f.state.currentReads,1);assert.equal(f.state.signs,1);}finally{loan?.close();f.client.disposeReceive();assert.equal(f.timers.size,0);}
});

test('currentSource의 profile FETCH/BODY 대기는 caller abort·loan close·Client dispose에 정착하고 소유43B를 즉시 지운다',async()=>{
 for(const stage of ['FETCH','BODY'])for(const action of ['ABORT','CLOSE','DISPOSE']){const f=await phaseHttpFixture('STREAM'),owned:Buffer[]=[];let loan:any,pending:Promise<unknown>|undefined;try{await f.client.consumeReceivePhase(f.input.window,f.input.challenge,f.input.request,f.input.body,f.source);const from=Buffer.from;try{(Buffer as any).from=(...args:any[])=>{const result=Reflect.apply(from,Buffer,args)as Buffer;if(args[0] instanceof Uint8Array&&args[0].byteLength===43)owned.push(result);return result;};loan=f.client.createDeliveryCurrentSource();}finally{Buffer.from=from;}assert.equal(owned.length,1);f.state.currentMode='PROFILE_HOLD_'+stage;const controller=new AbortController();let settled=false;pending=loan.source.read(controller.signal);void pending!.then(()=>{settled=true;},()=>{settled=true;});for(let i=0;i<300&&!f.state.profileEntered;i++)await Promise.resolve();assert.equal(f.state.profileEntered,true);for(let i=0;i<10;i++)await Promise.resolve();if(action==='ABORT')controller.abort();else if(action==='CLOSE')loan.close();else f.client.disposeReceive();for(let i=0;i<300&&!settled;i++)await Promise.resolve();assert.equal(settled,true,stage+'/'+action+' 원 profile await가 정착해야 한다');await assert.rejects(pending!);assert.equal(f.state.profileAborted,true,'profile fetch에 전달된 실제 signal도 취소한다');assert.ok(owned[0]!.every(byte=>byte===0));assert.equal(f.state.currentReads,undefined);f.state.releaseProfile();await assert.rejects(loan.source.read(new AbortController().signal));assert.equal(f.state.currentReads,undefined);}finally{loan?.close();f.client.disposeReceive();f.state.releaseProfile?.();await pending?.catch(()=>{});assert.equal(f.timers.size,0);}}
});
